With the number of widgets you're wrapping, it might be more practical to keep them mounted but only switch their visibility with CSS (you'll need an actual HTML element to contain all the children though), something like:

```tsx
import React from "react";
import { useInstantSearch } from "react-instantsearch";

export function Layout(props) {
  const { children } = props;
  const { status, results } = useInstantSearch();

  const isFetching = status === "loading" || status === "stalled";

  return (
    <React.Fragment>
      <h1 style={{ display: isFetching ? 'block' : 'none' }}>loading</h1>
      <div style={{ display: isFetching ? 'none' : 'block' }}>{children}</div>
    </React.Fragment>
  );
}
```
